PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate WHERE {
  VALUES ?person { 
    <http://dbpedia.org/resource/Tera_Moody> 
    <http://dbpedia/property/Frank_Cignetti_Jr.>  # placeholder for correct IRI
  }
  OPTIONAL { ?person dbp:birthDate ?date1 . }
  OPTIONAL { ?person dbo:birthDate ?date2 . }
  BIND (COALESCE(?date1, ?date2) AS ?birthDate)
}
LIMIT 100

